"""Domain exception specifications."""
from typing import Dict, Any, Optional

class ServiceError(Exception):
    def __init__(self, code: str, message: str = "", details: Optional[Dict[str, Any]] = None):
        super().__init__(f"[{code}] {message}")
        self.code = code
        self.message = message
        self.details = details or {}

    def to_dict(self) -> Dict[str, Any]:
        return {"code": self.code, "message": self.message, "details": self.details}

class LockConflictError(ServiceError):
    """Exception raised when a resource lock cannot be acquired due to an existing lock."""
    def __init__(self, resource_id: str, owner_id: str, existing_owner_id: str, message: str = "", details: Optional[Dict[str, Any]] = None):
        if not message:
            message = f"Resource '{resource_id}' is locked by '{existing_owner_id}' and cannot be acquired by '{owner_id}'."

        super().__init__(
            code="LOCK_CONFLICT",
            message=message,
            details={
                "resource_id": resource_id,
                "owner_id": owner_id,
                "existing_owner_id": existing_owner_id,
                **(details or {})
            }
        )
